import React, { useState } from "react";
import "./Form.css";

function Form() {
  const [skills, setSkills] = useState([""]);

  // Add a new skill input
  const handleAddSkill = () => {
    setSkills([...skills, ""]);
  };

  // Update the value of a specific skill
  const handleSkillChange = (index, value) => {
    const updatedSkills = [...skills];
    updatedSkills[index] = value;
    setSkills(updatedSkills);
  };

  // Remove a specific skill input
  const handleRemoveSkill = (index) => {
    const updatedSkills = skills.filter((_, i) => i !== index);
    setSkills(updatedSkills);
  };

  // Handle form submission
  const handleSubmit = (event) => {
    event.preventDefault();
    console.log("Submitted Skills:", skills);
  };

  return (
    <div className="form-container">
      <h2>PROFILE</h2>
      <input type="text" placeholder="Name" required />
      <input type="file" />
      <input type="text" placeholder="Role" required />
      <input type="date" required />

      <h2>ABOUT SECTION</h2>
      <textarea placeholder="Professional Summary" rows="4" cols="100" />

      {/* Skills Section */}
      <form onSubmit={handleSubmit} className="form">
        <h2>Add Your Skills</h2>
        {skills.map((skill, index) => (
          <div key={index} className="input-group">
            <input
              type="text"
              value={skill}
              onChange={(e) => handleSkillChange(index, e.target.value)}
              placeholder={`Skill ${index + 1}`}
              className="input"
            />
            <button
              type="button"
              onClick={() => handleRemoveSkill(index)}
              className="remove"
            >
              Remove
            </button>
          </div>
        ))}
        <div className="button-group">
          <button type="button" onClick={handleAddSkill}>
            Add Skill
          </button>
          <button type="submit">Submit</button>
        </div>
      </form>
    </div>
  );
}

export default Form;
